void Lavel()
{
    // Level 2
    if (Road1 > 125 && Road1 < 350)
    {
        LavelNum.Text = "2";
        if (speed1 < 100) speed1++;
        LinesTimer.Interval = 125;
        ChoseTimer.Interval = 100;
        move = 16;
        RedCar.Image = frm1.RaceType.Checked ? BlueCar2.Image : BlackCar2.Image;
    }
    // Level 3
    else if (Road1 > 350 && Road1 < 600)
    {
        LavelNum.Text = "3";
        if (speed1 < 125) speed1++;
        LinesTimer.Interval = 100;
        ChoseTimer.Interval = 75;
        move = 18;
        RedCar.Image = frm1.RaceType.Checked ? WhiteCar3.Image : BlackCar3.Image;
    }
    // ... higher levels follow the same pattern
}

void CarsShow(PictureBox pb)
{
    int r = rnd.Next(0, 4);
    switch (r)
    {
        case 0: pb.Image = Properties.Resources.car0; break;
        case 1: pb.Image = Properties.Resources.car1; break;
        case 2: pb.Image = Properties.Resources.car2; break;
        case 3: pb.Image = Properties.Resources.car3; break;
    }
    pb.SizeMode = PictureBoxSizeMode.StretchImage;
}

class CarChoos
{
    public bool ObstacleCar = false;
    public PictureBox Cars;
    public bool time = false;
}

private void Form1_Load(object sender, EventArgs e)
{
    SCORE.Text = Settings1.Default.Score.ToString() + " M";
}

private void START_Click(object sender, EventArgs e)
{
    this.Hide();
    Form2 frm2 = new Form2();
    frm2.Show();
}

private void Form1_KeyDown(object sender, KeyEventArgs e)
{
    if (e.KeyCode == Keys.Escape)
        Application.Exit();
}

private void Form3_Load(object sender, EventArgs e)
{
    Form2 frm2 = Application.OpenForms["Form2"] as Form2;
    RoadEd.Text = "Road :" + frm2.Road0.Text;
    ScoreEd.Text = "Score : " + Settings1.Default.Score.ToString() + " m";

    // Highlight new record in red
    if (Settings1.Default.Score <= Convert.ToInt32(
        frm2.Road0.Text.Substring(0, frm2.Road0.Text.Length - 1)))
    {
        ScoreEd.BackgroundImage = RedLine.Image;
        ScoreEd.ForeColor = Color.White;
    }
}

private void play_Click(object sender, EventArgs e)
{
    Form2 frm2 = new Form2();
    this.Close();
    frm2.Show();
}

private void Exit_Click(object sender, EventArgs e)
{
    Form1 frm1 = new Form1();
    this.Close();
    frm1.Show();
}
